script:
(function () {
  'use strict';

  var GUIDE = {"windows": {"label": "Windows", "browsers": {"chrome": {"label": "Chrome / Edge", "allow": ["Click the camera icon (or the lock/info icon) at the left of the address bar.", "Find “Camera” and “Microphone” in the list and set each to Allow.", "Reload the page."], "reset": ["Click the lock/info icon in the address bar, then “Site settings.”", "Set Camera and Microphone back to “Ask (default)” or “Allow.”", "Reload the page and try again — the prompt should reappear if you chose Ask."]}, "firefox": {"label": "Firefox", "allow": ["Click the lock icon in the address bar.", "Find the camera/microphone permission entry and choose Allow.", "Reload the page."], "reset": ["Click the lock icon in the address bar, then the arrow next to the blocked camera/microphone entry.", "Choose “Remove Permission” or set it to Allow directly.", "Reload the page — you should see the permission prompt again."]}}}, "mac": {"label": "macOS", "browsers": {"chrome": {"label": "Chrome", "allow": ["Click the camera icon in the address bar and choose “Always allow.”", "Separately, make sure macOS itself allows it: System Settings → Privacy & Security → Camera (and Microphone), and enable Chrome in both lists.", "Reload the page."], "reset": ["Click the lock/info icon in the address bar, then “Site settings.”", "Set Camera and Microphone back to “Ask (default)” or “Allow.”", "Reload the page and try again."]}, "firefox": {"label": "Firefox", "allow": ["Click the lock icon in the address bar and allow the camera/microphone permission.", "Also check System Settings → Privacy & Security → Camera (and Microphone) and make sure Firefox is enabled there too — macOS blocks access at the OS level independently of what Firefox allows.", "Reload the page."], "reset": ["Click the lock icon, then the arrow next to the blocked permission entry, and remove or change it.", "Reload the page — the prompt should reappear."]}, "safari": {"label": "Safari", "allow": ["Safari → Settings → Websites → Camera (and separately Microphone).", "Find this site in the list and set it to Allow.", "Also check System Settings → Privacy & Security → Camera/Microphone and make sure Safari is enabled there.", "Reload the page."], "reset": ["Safari → Settings → Websites → Camera, find this site, and change it from Deny to Allow (or to Ask).", "Do the same on the Microphone tab if audio is also blocked.", "Reload the page."]}}}, "android": {"label": "Android", "browsers": {"chrome": {"label": "Chrome", "allow": ["Tap the lock/info icon at the left of the address bar.", "Tap Permissions, then set Camera and Microphone to Allow.", "Reload the page."], "reset": ["Tap the lock/info icon in the address bar, then Permissions, and change Camera/Microphone from Blocked to Allow (or Ask).", "If that section doesn't appear, go to Android Settings → Apps → Chrome → Permissions → Camera/Microphone and allow it at the app level, then reload the page."]}, "firefox": {"label": "Firefox", "allow": ["Tap the lock icon in the address bar and allow the camera/microphone permission when prompted.", "Also check Android Settings → Apps → Firefox → Permissions → Camera/Microphone and make sure both are allowed there.", "Reload the page."], "reset": ["Android Settings → Apps → Firefox → Permissions → Camera (and Microphone), and set each to Allow.", "Reload the page and try again."]}}}, "ios": {"label": "iOS / iPadOS", "browsers": {"safari": {"label": "Safari", "allow": ["Settings app → Safari → Camera (and separately Microphone), and set to Allow.", "Alternatively, on the page itself: tap “AA” in the address bar → Website Settings, and set Camera/Microphone to Allow there.", "Reload the page."], "reset": ["Settings app → Safari → Camera, and change it from Deny to Allow (or Ask).", "Do the same under Microphone if audio is blocked too.", "Reload the page."]}, "chrome": {"label": "Chrome", "allow": ["iOS Chrome uses Apple's underlying WebKit engine, so camera/microphone permission is actually controlled by the Settings app, not inside Chrome itself: Settings app → Chrome → Camera (and Microphone), set to Allow.", "Reload the page in Chrome."], "reset": ["Settings app → Chrome → Camera (and Microphone), and change from off to on.", "Reload the page."]}}}};
  var PLATFORM_ORDER = ["windows", "mac", "android", "ios"];

  var platformTabs = document.getElementById('platformTabs');
  var browserTabs = document.getElementById('browserTabs');
  var guideContent = document.getElementById('guideContent');

  var currentPlatform = null;
  var currentBrowser = null;

  function escapeHtml(s) {
    var d = document.createElement('div');
    d.textContent = String(s);
    return d.innerHTML;
  }

  // Preselects the visitor's own platform/browser via simple UA sniffing,
  // per this tool's own spec -- always overridable via the tabs, never
  // the only way to reach a given combination.
  function detectPlatform() {
    var ua = navigator.userAgent || '';
    if (/iPhone|iPad|iPod/.test(ua)) return 'ios';
    if (/Android/.test(ua)) return 'android';
    if (/Macintosh|Mac OS X/.test(ua)) return 'mac';
    return 'windows';
  }

  function detectBrowser(platformKey) {
    var ua = navigator.userAgent || '';
    var browsers = GUIDE[platformKey].browsers;
    var guess;
    if (/Firefox/.test(ua)) guess = 'firefox';
    else if (/Safari/.test(ua) && !/Chrome|Chromium|CriOS/.test(ua)) guess = 'safari';
    else guess = 'chrome'; // covers Chrome, Edge (Edg/), and CriOS (Chrome on iOS)
    return browsers[guess] ? guess : Object.keys(browsers)[0];
  }

  function renderPlatformTabs() {
    platformTabs.innerHTML = PLATFORM_ORDER.map(function (key) {
      var active = key === currentPlatform;
      return '<button type="button" class="btn-secondary' + (active ? ' active' : '') + '" data-platform="' + key + '" aria-pressed="' + active + '">' + escapeHtml(GUIDE[key].label) + '</button>';
    }).join('');
    Array.prototype.forEach.call(platformTabs.querySelectorAll('button'), function (btn) {
      btn.addEventListener('click', function () { selectPlatform(btn.getAttribute('data-platform')); });
    });
  }

  function renderBrowserTabs() {
    var browsers = GUIDE[currentPlatform].browsers;
    browserTabs.innerHTML = Object.keys(browsers).map(function (key) {
      var active = key === currentBrowser;
      return '<button type="button" class="btn-secondary' + (active ? ' active' : '') + '" data-browser="' + key + '" aria-pressed="' + active + '">' + escapeHtml(browsers[key].label) + '</button>';
    }).join('');
    Array.prototype.forEach.call(browserTabs.querySelectorAll('button'), function (btn) {
      btn.addEventListener('click', function () { selectBrowser(btn.getAttribute('data-browser')); });
    });
  }

  function renderContent() {
    var entry = GUIDE[currentPlatform].browsers[currentBrowser];
    function stepList(steps) {
      return '<ol>' + steps.map(function (s) { return '<li>' + escapeHtml(s).replace(/&quot;/g, '"') + '</li>'; }).join('') + '</ol>';
    }
    var labelStyle = 'font-weight:700;color:var(--text);margin:0 0 .5rem';
    guideContent.innerHTML =
      '<p style="' + labelStyle + '">Allow camera &amp; microphone access</p>' + stepList(entry.allow) +
      '<p style="' + labelStyle + ';margin-top:1.25rem">Reset a previously blocked permission</p>' + stepList(entry.reset);
  }

  function selectPlatform(key) {
    if (!GUIDE[key]) return;
    currentPlatform = key;
    currentBrowser = detectBrowser(key);
    renderPlatformTabs();
    renderBrowserTabs();
    renderContent();
  }

  function selectBrowser(key) {
    if (!GUIDE[currentPlatform].browsers[key]) return;
    currentBrowser = key;
    renderBrowserTabs();
    renderContent();
  }

  selectPlatform(detectPlatform());
})();
